/** Real FeedClient transport, streamed XML, retry state, connect UI and optional public-feed probes. */
public final class TenFeedSmoke extends TenThemeSmoke {
    static final String GOOD="https://example.org/feed.xml";final StringBuilder live=new StringBuilder("Source\tResult\tStories\tDecoded bytes read\tDetail\n");
    @Override public void onStart(){Bundle output=new Bundle();try{
        store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putBoolean("ten_news_images",false).putBoolean("weather_follow",false).commit();TenThemes.TEN.get(2).apply(store);
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.description(root,"Start menu")!=null,"Shell ready");
        parsing();firstRetry();network();configuration();liveFeeds();
        output.putString("stream","PASS: streamed multi-megabyte and gzip RSS, Atom/relative links/encoding, bounded input and DTD rejection, immediate manual retry, cached-story and previous-feed retention, HTTP/HTML diagnostics, Retry-After, cancelled stale response protection, inline Connect feedback and both orientations; live source outcomes are in ten7-feed-live.tsv\n");finish(Activity.RESULT_OK,output);
    }catch(Throwable error){try{shot("ten7-failure");}catch(Exception ignored){}output.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,output);}}
    byte[] xml(String prefix,int padding){StringBuilder out=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><rss xmlns:media=\"http://search.yahoo.com/mrss/\"><channel><title>Synthetic source</title>");for(int i=0;i<14;i++)out.append("<item><title>").append(prefix).append(' ').append(i).append("</title><link>https://example.org/story/").append(prefix).append('/').append(i).append("</link><description><![CDATA[<p>A short synthetic summary.</p>]]></description><media:thumbnail url=\"https://example.org/image.jpg\"/></item>");out.append("<!--");for(int i=0;i<padding;i++)out.append('x');out.append("--></channel></rss>");return out.toString().getBytes(StandardCharsets.UTF_8);}
    void parsing()throws Exception{
        check(!FeedClient.validUrl("http://example.org/feed")&&!FeedClient.validUrl("https://user@example.org/feed")&&!FeedClient.validUrl("https://example.org/a\nb\nc"),"Unsafe or malformed feed addresses are rejected before connecting");
        JSONArray atom=FeedClient.parse("<feed xmlns='http://www.w3.org/2005/Atom'><entry><title>Atom &amp; title</title><source><title>Not the headline</title></source><link rel='self' href='/self'/><link rel='alternate' href='/story'/><content type='html'>&lt;p&gt;A summary&lt;/p&gt;</content></entry></feed>",GOOD);check(atom.length()==1&&atom.getJSONObject(0).getString("title").equals("Atom & title")&&atom.getJSONObject(0).getString("url").equals("https://example.org/story")&&atom.getJSONObject(0).getString("summary").equals("A summary"),"Atom, nested source title, entity and relative links");
        String utf="<?xml version='1.0' encoding='UTF-16'?><rss><channel><item><title>Café 漫画</title><link>https://example.org/utf</link></item></channel></rss>";try(FeedXml.Limited stream=new FeedXml.Limited(new ByteArrayInputStream(utf.getBytes(StandardCharsets.UTF_16)))){check(FeedXml.parse(stream,GOOD,null).getJSONObject(0).getString("title").equals("Café 漫画"),"XML encoding detection");}
        boolean rejected=false;try{FeedClient.parse("<!DOCTYPE rss [<!ENTITY e SYSTEM 'file:///etc/passwd'>]><rss><channel><item><title>&e;</title></item></channel></rss>",GOOD);}catch(Exception expected){rejected=true;}check(rejected,"DTD is rejected before resolving entities");
        JSONArray empty=FeedClient.parse("<rss><channel><title>Empty source</title></channel></rss>",GOOD);check(empty.length()==0,"A valid empty feed remains distinguishable from an error");
        boolean bounded=false;InputStream huge=new SequenceInputStream(new ByteArrayInputStream("<rss><channel><description>".getBytes(StandardCharsets.UTF_8)),new InputStream(){int left=FeedXml.MAX_BYTES+100000;public int read(){return left-->0?'x':-1;}public int read(byte[] b,int offset,int length){if(left<=0)return -1;int n=Math.min(length,left);Arrays.fill(b,offset,offset+n,(byte)'x');left-=n;return n;}});try(FeedXml.Limited stream=new FeedXml.Limited(huge)){FeedXml.parse(stream,GOOD,null);}catch(IOException expected){bounded=String.valueOf(expected.getMessage()).contains("FEED_TOO_LARGE");}check(bounded,"Oversized input remains bounded");
    }
    void clear(){store.prefs.edit().putString("feed_url","").putString("feed_items","[]").remove("feed_updated").remove("feed_expires").remove("feed_error").remove("feed_error_url").remove("feed_retry_at").remove("feed_retry_server").commit();}
    void firstRetry()throws Exception{clear();Script replies=new Script();FeedClient client=new FeedClient(store,()->{},replies,System::currentTimeMillis);replies.add(403,new byte[0]);ui(()->client.configure(GOOD));await(()->!client.loading(),"First connection fails");check(client.url().isEmpty()&&!client.error().isEmpty(),"A failed first source is not saved");replies.add(200,xml("FirstRetry",0));ui(()->client.refresh(true));await(()->!client.loading(),"Refresh retries the attempted first source");check(client.url().equals(GOOD)&&FeedClient.items(store).length()==12,"Refresh works before any source has connected successfully");client.close();}
    void network()throws Exception{
        clear();Script script=new Script();AtomicLong now=new AtomicLong(System.currentTimeMillis());FeedClient client=new FeedClient(store,()->{},script,now::get);byte[] large=xml("Large",2_500_000);script.add(200,large);final int[] token={-1};ui(()->token[0]=client.configure(GOOD));await(()->!client.loading(),"Large feed completes");check(client.succeeded(token[0])&&FeedClient.items(store).length()==12&&client.lastBytes<large.length/2,"A multi-megabyte feed streams the first twelve cards without downloading its tail");long expiry=store.prefs.getLong("feed_expires",0);int requests=script.calls.get();ui(()->client.active(true));check(script.calls.get()==requests,"Automatic refresh respects a successful fresh cache");
        script.add(404,new byte[0]);ui(()->client.refresh(true));await(()->!client.loading(),"HTTP error reported");check(client.error().contains("404")&&FeedClient.items(store).length()==12&&store.prefs.getLong("feed_expires",0)==expiry,"HTTP status is actionable and cached stories survive");
        script.add(200,xml("Retry",0));ui(()->client.refresh(true));await(()->!client.loading(),"Immediate manual retry");check(script.calls.get()==requests+2&&FeedClient.items(store).getJSONObject(0).getString("title").equals("Retry 0"),"Manual retry is not locked out by the old fifteen-minute success expiry or failure backoff");
        script.add(200,"<!doctype html><html><body>A web page</body></html>".getBytes(StandardCharsets.UTF_8));ui(()->token[0]=client.configure("https://example.org/page"));await(()->!client.loading(),"HTML rejected");check(client.error().contains("web page")&&client.url().equals(GOOD)&&FeedClient.items(store).getJSONObject(0).getString("title").equals("Retry 0"),"A failed new source keeps the old configuration and cache");
        script.add(403,new byte[0]);ui(()->token[0]=client.configure("https://example.org/denied"));await(()->!client.loading(),"Access denial reported");check(client.error().contains("denied access")&&client.url().equals(GOOD),"403 is distinguished from parser and network errors");
        Fake rate=script.add(429,new byte[0]);rate.headers.put("Retry-After","120");ui(()->client.refresh(true));await(()->!client.loading(),"Rate limit reported");int limited=script.calls.get();ui(()->client.refresh(true));check(script.calls.get()==limited&&client.error().contains("asked us to wait"),"Server Retry-After is respected even on manual refresh");now.addAndGet(121000);script.add(200,xml("AfterLimit",0));ui(()->client.refresh(true));await(()->!client.loading(),"Refresh after server delay");check(FeedClient.items(store).getJSONObject(0).getString("title").equals("AfterLimit 0"),"Refresh resumes after Retry-After");
        CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);Fake delayed=script.add(200,xml("Stale",0));delayed.entered=entered;delayed.release=release;ui(()->token[0]=client.configure("https://example.org/stale"));check(entered.await(5,TimeUnit.SECONDS),"Delayed request began");ui(()->client.cancelConfiguration(token[0]));script.add(200,xml("Newest",0));ui(()->token[0]=client.configure("https://example.org/newest"));release.countDown();await(()->!client.loading(),"Replacement request completes");check(client.succeeded(token[0])&&client.url().endsWith("/newest")&&FeedClient.items(store).getJSONObject(0).getString("title").equals("Newest 0"),"A cancelled response cannot replace a newer source");client.close();
    }
    void configuration()throws Exception{
        clear();Script script=new Script();script.add(200,"<!doctype html><html>A website</html>".getBytes(StandardCharsets.UTF_8));Fake gzip=script.add(200,gzip(xml("Connected",2_500_000)));gzip.headers.put("Content-Encoding","gzip");final TenNews[] board={null};ui(()->{store.prefs.edit().putBoolean("ten_news_images",false).putString("ten_saved_news","[{\"title\":\"Preserved bookmark\",\"url\":\"https://example.org/bookmark\"}]").commit();board[0]=new TenNews(home,store,home::open,null,script,System::currentTimeMillis);((FrameLayout)home.findViewById(android.R.id.content)).addView(board[0],new FrameLayout.LayoutParams(-1,-1));board[0].configure();});
        setSystemText("News feed address","https://example.org/webpage");systemClick("Connect");await(()->!board[0].feed.loading()&&!board[0].feed.error().isEmpty(),"Inline setup error ready");check(awaitSystem("Feed connection result").getText().toString().contains("web page")&&awaitSystem("News feed address").isEnabled(),"Dialog stays open with a readable error and editable address");check(store.prefs.getString("feed_url","").isEmpty(),"Failed setup does not save a broken source");shot("ten7-feed-error");
        setSystemText("News feed address",GOOD);systemClick("Connect");await(()->TenSmoke.description(board[0],"News story: Connected 0")!=null,"Successful connection creates real cards");check(board[0].feed.url().equals(GOOD)&&FeedClient.items(store).length()==12&&store.prefs.getString("ten_saved_news","").contains("Preserved bookmark"),"Gzip source connects and saved stories survive");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->root.getHeight()>root.getWidth(),"Portrait feed");shot("ten7-news-portrait");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Landscape feed");shot("ten7-news-landscape");ui(()->((FrameLayout)board[0].getParent()).removeView(board[0]));
    }
    byte[] gzip(byte[] bytes)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();try(GZIPOutputStream gzip=new GZIPOutputStream(out)){gzip.write(bytes);}return out.toByteArray();}
    void liveFeeds()throws Exception{for(String address:new String[]{FeedClient.BBC,FeedClient.TECHRADAR}){final FeedClient client=new FeedClient(store,()->{});final int[] token={-1};ui(()->token[0]=client.configure(address));long end=SystemClock.uptimeMillis()+30000;while(client.loading()&&SystemClock.uptimeMillis()<end)Thread.sleep(80);boolean success=client.succeeded(token[0]);String detail=success?"HTTPS streaming transport and Android parser":"Live provider unavailable: "+client.error();live.append(FeedClient.source(address)).append('\t').append(success?"PASS":"UNAVAILABLE").append('\t').append(success?FeedClient.items(store).length():0).append('\t').append(client.lastBytes).append('\t').append(detail.replace('\t',' ')).append('\n');client.close();}try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(getTargetContext().getFilesDir(),"ten7-feed-live.tsv")),StandardCharsets.UTF_8)){out.write(live.toString());}}
    static final class Script implements FeedClient.Connections {final Queue<Fake> queue=new ConcurrentLinkedQueue<>();final AtomicInteger calls=new AtomicInteger();Fake add(int status,byte[] data)throws Exception{Fake fake=new Fake(status,data);queue.add(fake);return fake;}public HttpURLConnection open(URL url)throws IOException{calls.incrementAndGet();Fake fake=queue.poll();if(fake==null)throw new IOException("No scripted reply");return fake;}}
    static final class Fake extends HttpURLConnection {final int status;final byte[] data;final Map<String,String> headers=new ConcurrentHashMap<>();CountDownLatch entered,release;Fake(int status,byte[] data)throws Exception{super(new URL(GOOD));this.status=status;this.data=data;headers.put("Content-Type","application/rss+xml; charset=utf-8");}public int getResponseCode()throws IOException{if(entered!=null){entered.countDown();try{if(!release.await(8,TimeUnit.SECONDS))throw new SocketTimeoutException();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException(e);}}return status;}public InputStream getInputStream(){return new ByteArrayInputStream(data);}public String getHeaderField(String name){return headers.get(name);}public String getContentType(){return headers.get("Content-Type");}public String getContentEncoding(){return headers.get("Content-Encoding");}public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}}
}
